Chapter.Code:
float DistributionGGX(
    vec3 N,
    vec3 H,
    float roughness)
{
    float alpha  = roughness * roughness;
    float alpha2 = alpha * alpha;

    float NdotH =
        max(dot(N, H), 0.0);

    float d =
        NdotH * NdotH *
        (alpha2 - 1.0) + 1.0;

    return alpha2 /
        (Pi * d * d);
}

